const FREE_BOARD = [
  {t:"帮集市城的粮商押送一车粮食到灰港",check:{a:"STR",sk:"athletic",label:"押运"},ok:["你押着粮车穿过集市，一路平安。粮商多给了几个铜星，还送了你一袋干粮。"],fail:["路上遇上一伙小贼。你费了点手脚才脱身，粮袋破了个口子。"],okEff:{gold:12,xp:20},failEff:{gold:4,xp:8}},
  {t:"替冒险者公会把一封信送到灰港码头",check:{a:"AGI",sk:"stealth",label:"送信"},ok:["信送到了。接信的是个沉默的汉子，只点了点头。公会的人多看了你一眼：“腿脚麻利。”"],fail:["你在灰港的雾里迷了路，绕了半天才找到地方。信送到了，人累得够呛。"],okEff:{gold:10,xp:15,rep:1},failEff:{gold:3,xp:6}},
  {t:"在集市城帮人看一天铺子，学学买卖",check:{a:"CHA",sk:"bargain",label:"看铺"},ok:["你学得很快，一天下来，帮掌柜多卖了三成。掌柜乐得合不拢嘴，多给了工钱。"],fail:["你嘴笨，一天没卖出几件。掌柜摆摆手，少给了工钱。"],okEff:{gold:14,xp:15},failEff:{gold:4,xp:6}}
]; window.FREE_BOARD = FREE_BOARD; /* /v60inj:winx2:FREE_BOARD/ */



const NORTH_BOARD = [
  {t:"护送军粮到铁壁城外围哨所",check:{a:"STR",sk:"martial",label:"护送"},ok:["你护送着军粮车队，一路平安抵达哨所。哨所的老兵塞给你一份赏金：'乱世里，能平安运到，就是本事。'"],fail:["你们半路遇上一伙流民抢粮。你拼力保住了大部分，但丢了两袋。军需官扣了你一半赏金。"],okEff:{gold:20,xp:25,rep:2},failEff:{gold:8,xp:10}},
  {t:"替北境城的猎人送一封急信到河湾城",check:{a:"AGI",sk:"athletic",label:"送信"},ok:["你日夜兼程，把信送到河湾城。收信的粮商看完信，脸色一变，多给了你一份赏金：'你送的不是信，是命。'"],fail:["你半路淋了雨，信纸湿了半边。收信人脸色不好看，只给了你半份赏金。"],okEff:{gold:15,xp:20,rep:1},failEff:{gold:5,xp:8}},
  {t:"清理铁门关外围的一窝野狼",check:{a:"STR",sk:"martial",label:"猎杀"},ok:["你摸到狼窝，三只野狼。你干净利落地解决了它们，割下狼耳回去领赏。猎人点头：'利索。'"],fail:["狼比你想象的凶。你挂了彩才脱身，只打死一只。猎人叹了口气，给了你半份赏金。"],okEff:{gold:18,xp:25},failEff:{gold:6,xp:10,hp:-8}},
  {t:"帮矿山城的老铁匠送一箱精铁到艾尔达城",check:{a:"INT",sk:"bargain",label:"押运"},ok:["你搭上北上的商队，一路平安。老铁匠收到货款，多给你两枚银月：'路上没少斤两，好样的。'"],fail:["路上被圣痕司的关卡扣了箱，说你'运输军需物资无批文'。你交了罚金才过关。老铁匠脸色铁青。"],okEff:{gold:16,xp:20,rep:1},failEff:{gold:4,xp:8,rep:-1}},
  {t:"替河湾城的酒馆老板娘打捞沉在河里的酒桶",check:{a:"STR",sk:"athletic",label:"打捞"},ok:["你扎进河里，把三桶酒都捞了上来。老板娘眉开眼笑，请了你一顿晚饭，还送了你一壶好酒。"],fail:["河水太浑，你捞了半天，只捞起一桶。老板娘撇撇嘴，给了你一点辛苦钱。"],okEff:{gold:10,xp:15,item:"一壶好酒"},failEff:{gold:4,xp:8}},
  {t:"护送一位老学者翻越霜狼山脉支脉",check:{a:"SPR",sk:"will",label:"向导"},ok:["老学者腿脚不便，你一路搀扶，翻过山梁。他在山腰停下来，望着远方，忽然说：'年轻人，山的那边，是深渊的方向。别去太深。'"],fail:["山路难行，你们半路遇上塌方，绕了一天。老学者累得直喘气，赏金少给了一半。"],okEff:{gold:14,xp:25,rep:2,book:function(){const j=JOBS[S.job];return j.books[1]?j.books[1][0]:null;}},failEff:{gold:5,xp:10}}
]; window.NORTH_BOARD = NORTH_BOARD; /* /v60inj:winx2:NORTH_BOARD/ */
function shuffle(a){const r=a.slice();for(let i=r.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[r[i],r[j]]=[r[j],r[i]];}return r;}
