const SOUTH_BOARD = [
  {t:"护送一批魔械零件到商栈城",check:{a:"STR",sk:"martial",label:"护送"},ok:["你护送着零件车，一路平安。收货的匠人验了货，满意地多给了赏钱。"],fail:["半路遇上一伙想截货的，你拼力打退，但零件摔坏了一件。货主扣了赏金。"],okEff:{gold:22,xp:25,rep:2},failEff:{gold:8,xp:10}},
  {t:"替金秤家族送一封信到学术城（走'不那么显眼的路'）",check:{a:"AGI",sk:"stealth",label:"送信"},ok:["你绕开大路，把信安全送到。收信的老教授多给了你一份赏钱：'谨慎的人，值得加钱。'"],fail:["你半路被圣痕司的关卡盘问，信差点被搜走。你交了点罚金才脱身。"],okEff:{gold:20,xp:22,rep:2},failEff:{gold:5,xp:8}},
  {t:"帮炼金工坊采集一批'月光草'",check:{a:"SPR",sk:"survive",label:"采集"},ok:["你在城外的湿地找到月光草，采了满满一篮。工坊主很高兴，送你一瓶催化剂。"],fail:["月光草长在泥沼深处，你陷了半条腿才爬出来，只采到一小把。"],okEff:{gold:12,xp:18,item:"催化剂"},failEff:{gold:4,xp:8}},
  {t:"替港口城的船主清点'白帆号'的货物",check:{a:"INT",sk:"detect",label:"清点"},ok:["你清点了整船的货，发现账实相符，但有一批'药材'的封装方式，不像是药材。你记下了这一点。"],fail:["你清点到一半，被港务官叫停：'这船有检疫令，闲人免近。'"],okEff:{gold:16,xp:20,flag:"cargo_note"},failEff:{gold:5,xp:8}},
  {t:"给学术城的真理学社送一箱'旧纸'",check:{a:"CHA",sk:"persu",label:"运送"},ok:["你避开圣痕司的耳目，把一箱旧书送到真理学社。圆眼镜青年感激不尽，送你一份他们整理的《节点考》。"],fail:["你被巡兵拦下盘问，只得绕了大半个城才送到。"],okEff:{gold:14,xp:25,rep:2,book:function(){const j=JOBS[S.job];return j.books[2]?j.books[2][0]:null;}},failEff:{gold:5,xp:10}},
  {t:"帮商栈城的矿石贩子鉴定一批'沙漠料'",check:{a:"INT",sk:"lore",label:"鉴定"},ok:["你仔细甄别，从一堆'沙漠料'里挑出几块成色好的，也认出两块'沾了怪气'的。矿贩子很满意：'行家！'多给了赏钱。"],fail:["你看走了眼，把一块普通石头当成了好料。矿贩子摇摇头。"],okEff:{gold:18,xp:25,rep:1,mat:function(){const j=JOBS[S.job];return j.mats[2];}},failEff:{gold:6,xp:10}}
]; window.SOUTH_BOARD = SOUTH_BOARD; /* /v60inj:winx2:SOUTH_BOARD/ */
/*==STORY_SOUTH==*/


