const ELF_BOARD = [
  {t:"替森林城（北方）的猎户送信给精灵边境的巡林人",check:{a:"CHA",sk:"persu",label:"送信"},ok:["巡林人收了信，看了你一眼：'人类的信，能送到这里，不容易。'他给了你赏钱，又送了你一枚木哨：'林子里迷路，吹它。'"],fail:["巡林人拒收人类捎来的信：'边境规矩。'你只得原路返回。"],okEff:{gold:12,xp:20,item:"木哨"},failEff:{gold:4,xp:8}},
  {t:"替精灵采药人采集'月露草'",check:{a:"SPR",sk:"survive",label:"采集"},ok:["月露草长在晨雾里，你采了半篮。采药人点点头：'手脚利落。'多给了赏钱。"],fail:["月露草开在悬崖边，你够不着。"],okEff:{gold:14,xp:18},failEff:{gold:4,xp:8}},
  {t:"护送一位老学者到迷雾边缘",check:{a:"STR",sk:"athletic",label:"护送"},ok:["老学者腿脚慢，你一路照料。分别时，他送你一本笔记：《精灵史略》。"],fail:["路途泥泞，你们多走了半日。"],okEff:{gold:10,xp:15,item:"《精灵史略》"},failEff:{gold:4,xp:8}}
]; window.ELF_BOARD = ELF_BOARD; /* /v60inj:winx2:ELF_BOARD/ */
