const DWARF_BOARD = [
  {t:"帮铁匠铺的老巴德送一批'好钢'到矿山城",check:{a:"STR",sk:"athletic",label:"押运"},ok:["你押着好钢，翻山越岭送到矿山城。收货的铁匠验了钢，眼睛发亮：'好钢！'多给了赏钱。"],fail:["山路难行，你摔了一跤，钢料磕了角。铁匠脸色不好看。"],okEff:{gold:18,xp:22,rep:2},failEff:{gold:6,xp:10}},
  {t:"替老矿工送一壶酒到封矿道口（祭奠）",check:{a:"SPR",sk:"will",label:"送达"},ok:["你把酒放在矿道口的石台上，拜了拜。老矿工站在你身后，沉默许久，说：'祖宗们喝得到。'他给了你赏钱。"],fail:["矿道口有卫兵守着，你只得把酒放远了些。"],okEff:{gold:8,xp:15},failEff:{gold:3,xp:6}},
  {t:"帮大锻造师测试一柄新锻的战斧",check:{a:"STR",sk:"martial",label:"测试"},ok:["你挥舞战斧，劈断三根木桩。大锻造师看了直点头：'好腕力！'他送你一小块精钢。"],fail:["战斧太重，你抡了两下就脱了手。大锻造师摇摇头。"],okEff:{gold:12,xp:20,mat:function(){const j=JOBS[S.job];return j.mats[1];}},failEff:{gold:4,xp:8}},
  {t:"护送矮人商队到自由城邦",check:{a:"STR",sk:"martial",label:"护送"},ok:["矮人商队一路平安，抵达自由城邦。领队的矮人拍了拍你的肩（力道让你一个趔趄）：'人类，够义气！'"],fail:["半路遇上流民抢货，你拼力护住大部分。矮人领队叹了口气，给了半份赏金。"],okEff:{gold:20,xp:25,rep:2},failEff:{gold:8,xp:10}}
]; window.DWARF_BOARD = DWARF_BOARD; /* /v60inj:winx2:DWARF_BOARD/ */
