function isShopOpenV26(shopId) {
  initTimeV26();
  const shop = SHOPS_V26[shopId];
  if (!shop) return false;
  if (shop.restDay && S.time.dayOfWeek === shop.restDay) return false;
  const period = S.time.period;
  return (shop.priceMod[period] || 0) > 0;
}

